SELECT 'USER'      AS resultType,
       u.user_id   AS userId,
       u.nickname  AS userNickname,
       u.email     AS userEmail,
       u.role      AS title
FROM blog_user u
WHERE u.nickname LIKE #{likeKeyword}
   OR u.email LIKE #{likeKeyword}
ORDER BY u.user_id DESC
LIMIT #{limit}

SELECT 'VIOLATION' AS resultType, v.blog_id AS blogId, b.blog_name AS blogName, v.board_id AS boardId, v.user_id AS userId, u.nickname AS userNickname, u.email AS userEmail, v.attempted_title AS title, v.attempted_snippet AS snippet, v.matched_word AS matchedWord, v.writer_ip AS writerIp, DATE_FORMAT(v.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt FROM moderation_violations v LEFT JOIN blog b ON v.blog_id = b.blog_id LEFT JOIN blog_user u ON v.user_id = u.user_id
v.matched_word LIKE #{likeKeyword} OR v.attempted_title LIKE #{likeKeyword} OR u.nickname LIKE #{likeKeyword} OR u.email LIKE #{likeKeyword}
ORDER BY v.created_at DESC, v.violation_id DESC LIMIT #{limit}
